llm_calls.content:
{
  "task_summary": "Predict whether a person is employed using individual and household ACS characteristics in a way that should generalize across states.",
  "ranking": [
    {
      "rank": 1,
      "feature_id": 0,
      "rationale": "Age is a core, state-stable determinant of labor-force attachment and employment over the life cycle."
    },
    {
      "rank": 2,
      "feature_id": 1,
      "rationale": "Educational attainment strongly and broadly predicts employability across states and industries."
    },
    {
      "rank": 3,
      "feature_id": 4,
      "rationale": "Disability status has a direct, semantically robust relationship with employment capacity and participation."
    },
    {
      "rank": 4,
      "feature_id": 14,
      "rationale": "Cognitive difficulty is closely tied to ability to work and should transfer better than many demographic proxies."
    },
    {
      "rank": 5,
      "feature_id": 8,
      "rationale": "Military service status meaningfully affects current labor-force status through active duty, veteran status, and career pathways."
    },
    {
      "rank": 6,
      "feature_id": 12,
      "rationale": "Hearing difficulty can materially affect employment and is more causally relevant than geography-linked identity variables."
    },
    {
      "rank": 7,
      "feature_id": 13,
      "rationale": "Vision difficulty is another direct functional limitation with cross-state relevance for employment."
    },
    {
      "rank": 8,
      "feature_id": 2,
      "rationale": "Marital status correlates with household structure and labor supply decisions, though less directly than age or education."
    },
    {
      "rank": 9,
      "feature_id": 11,
      "rationale": "Relationship to householder captures household role and dependence, which can help distinguish likely workers from nonworkers."
    },
    {
      "rank": 10,
      "feature_id": 7,
      "rationale": "Citizenship status affects legal access to jobs and labor-market integration, but also partly reflects state-specific immigrant composition."
    },
    {
      "rank": 11,
      "feature_id": 10,
      "rationale": "Nativity has some predictive value for labor-market attachment but overlaps with citizenship and can encode regional composition."
    },
    {
      "rank": 12,
      "feature_id": 6,
      "rationale": "Recent mobility may relate to job transitions, but it is also sensitive to local housing and migration patterns."
    },
    {
      "rank": 13,
      "feature_id": 3,
      "rationale": "Sex is predictive in practice but is a demographic shortcut whose association with employment can vary across states and time."
    },
    {
      "rank": 14,
      "feature_id": 16,
      "rationale": "Grandparent caregiving status may affect availability for work, but it is niche and sparsely applicable."
    },
    {
      "rank": 15,
      "feature_id": 5,
      "rationale": "Parental employment status is mainly defined for children and is weak or awkward for the adult employment target population."
    },
    {
      "rank": 16,
      "feature_id": 15,
      "rationale": "Race often predicts via structural disparities, but for OOD generalization it is a brittle demographic shortcut with strong state-specific distributions."
    },
    {
      "rank": 17,
      "feature_id": 9,
      "rationale": "Ancestry is highly geography- and migration-pattern-dependent and is unlikely to be a stable semantic driver of employment across states."
    }
  ]
}
